public class OnlineStockSpanTest {

    @Test
    public void next_Nothing_Returns_1() {
        OnlineStockSpan onlineStockSpan = new OnlineStockSpan();
        int result = onlineStockSpan.next(0);
        assertEquals(1, result);
    }

    @Test
    public void next_SamePrice_Returns_1() {
        OnlineStockSpan onlineStockSpan = new OnlineStackSpan();
        onlineStackSpan.priceStack.push(-2);
        onlineStackSpan.stockPriceStack.push(-2);
        int result = onlineStackSpan.next(-2);
        assertEquals(1, result);
    }

    @Test
    public void next_DifferentPrices_Returns Span() {
        OnlineStockSpan onlineStackSpan = new OnlineStackSpan();
        onlineStackSpan.priceStack.push(-2);
        onlineStackSpan.stockPriceStack.push(-2);
        int result = onlineStackSpan.next(0);
        assertEquals(1, result);
        onlineStackSpan.priceStack.push(0);
        onlineStackSpan.stockPriceStack.push(0);
        result = onlineStackSpan.next(1);
        assertNotEquals(1, result);
    }

    @Test
    public void calculateSpans_EmptyArray_Returns_EmptyArray() {
        OnlineStockSpan onlineStockSpan = new OnlineStackSpan();
