    public void calculateSpans_MultipleElementsArray_Returns_CorrectSpans() {
        OnlineStockSpan onlineStockSpan = new OnlineStackSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{1, 2, 3, 4});
        assertEquals(0, result[0]);
        assertEquals(1, result[1]);
        assertEquals(2, result[2]);
        assertEquals(3, result[3]);
    }

    @Test
    public void calculateSpans_EmptyStockPriceStack_Returns_CorrectSpans() {
        OnlineStockSpan onlineStockSpan = new OnlineStackSpan();
        int[] result = onlineStockSpan.calculateSpans(new int[]{1, 2, 3, 4});
        assertEquals(0, result[0]);
        assertEquals(1, result[1]);
        assertEquals(2, result[2]);
        assertEquals(3, result[3]);
    }

    @Test
    public void calculateSpans_MultipleElementsStockPriceStack_Returns_CorrectSpans() {
        OnlineStockSpan onlineStackSpan = new OnlineStackSpan();
        for (int i = 1; i <= 4; i++) {
            int price = i;
            int result = onlineStackSpan.next(price);
            onlineStackSpan.stockPriceStack.push(price);
            when(onlineStackSpan.priceStack).thenReturn(new Stack<>());
            when(onlineStackSpan.stockPriceStack).thenReturn(new Stack<>());
            int[] spans = onlineStackSpan.calculateSpans(new int[]{});
            assertEquals(0, spans[0]);
            assertEquals(result, spans[1]);
        }
    }

    @Test
    public void next_StackPop() {
        OnlineStockSpan onlineStockSpan = new OnlineStackSpan();
        int result = onlineStockSpan.next(0);
        assertNull(onlineStockSpan.priceStack.pop());
        result = onlineStackSpan.next(1);
        assertNotEquals(1, onlineStockSpan.priceStack.pop());
    }

    @Test
    public void next_StackPopTwo() {
        OnlineStockSpan onlineStockSpan = new OnlineStackSpan();
        int result = onlineStockSpan.next(0);
        assertNull(onlineStockSpan.priceStack.pop());
        result = onlineStockSpan.next(1);
        assertNull(onlineStockSpan.priceStack.pop());
        result = onlineStockSpan.next(-2);
        assertNotEquals(1, onlineStockSpan.priceStack.pop());
    }

    @Test
    public void next_StackPopThree() {
        OnlineStockSpan onlineStockSpan = new OnlineStackSpan();
        int result = onlineStockSpan.next(0);
        assertNull(onlineStockSpan.priceStack.pop());
        result = onlineStockSpan.next(1);
        assertNull(onlineStockSpan.priceStack.pop());
        result = onlineStockSpan.next(-2);
        assertNull(onlineStockSpan.priceStack.pop());
    }

    private static class OnlineStackSpan extends OnlineStockSpan {
        Stack<Integer> priceStack = new Stack<>();
        List<Integer> stockPriceStack = new ArrayList<>();

        @Override
        public int next(int price) {
            while (!priceStack.isEmpty() && stockPriceStack.get(priceStack.peek()) <= price) {
                priceStack.pop();
            }
            if (priceStack.isEmpty()) {
                stockPriceStack.add(0);
            } else {
                stockPriceStack.add(stockPriceStack.get(priceStack.peek()));
            }
            int span = priceStack.size() + 1;
            priceStack.push(price);
            return span;
        }

        @Override
        public int[] calculateSpans(int[] prices) {
            int[] result = new int[prices.length];
            for (int i = 0; i < prices.length; i++) {
                int index = 0;
                while (!priceStack.isEmpty() && stockPriceStack.get(priceStack.peek()) <= prices[i]) {
                    priceStack.pop();
                    index++;
                }
                if (priceStack.isEmpty()) {
                    result[i] = 1;
                } else {
                    result[i] = index + 1;
                }
            }
            return result;
        }
    }
}
